    }
    if (clippedStart.getMillis() != firstStart.getMillis()) {
      Interval clippedFirstInterval = new Interval(clippedStart, firstEnd);
      VersionType firstVersion = firstEntry.getVersion();
      Interval firstTrueInterval = firstEntry.getTrueInterval();
      PartitionHolder<ObjectType> firstObject = firstEntry.getObject();
      retVal.set(
          0,
          new TimelineObjectHolder<>(
              clippedFirstInterval,
              firstTrueInterval,
              firstVersion,
              firstObject
          )
      );
    }
  }

  TimelineObjectHolder<VersionType, ObjectType> lastEntry = retVal.get(retVal.size() - 1);
  Interval lastInterval = lastEntry.getInterval();
  if (interval.overlaps(lastInterval)) {
    DateTime lastStart = lastInterval.getStart();
    DateTime lastEnd = lastInterval.getEnd();
    DateTime clippedEnd = lastEnd;
    if (queryComparableAsString) {
